import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-18","description":"","frontmatter":{"title":"AI 动态 · 2026-11-18","date":"2026-11-18T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-18.md","filePath":"news/2026-11/ai-news-2026-11-18.md","lastUpdated":null}'),r={name:"news/2026-11/ai-news-2026-11-18.md"};function i(o,e,l,p,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-11-18" tabindex="-1">AI 动态 · 2026-11-18 <a class="header-anchor" href="#ai-动态-·-2026-11-18" aria-label="Permalink to &quot;AI 动态 · 2026-11-18&quot;">​</a></h1><blockquote><p>截至 2026-11-18。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>OpenAI 发布 GPT-6.2 Astra 与 Sol，Astra API 降价 20% 至 $8/$40 每百万 token，但早期用户评价两极。</li><li>Nvidia 在黄仁勋离任后宣布停止向中国出货 Hopper 数据中心产品，同时初创投资组合价值膨胀至 $65B。</li><li>开发者侧，Claude Code 加入 JavaScript 链式工具调用，GitHub 推出跨设备 Agent Host Protocol，前端关注 State of HTML 2026 结果。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="gpt-6-2-astra-与-sol-上线遭重度用户差评-「基本不可用」" tabindex="-1">GPT-6.2 Astra 与 Sol 上线遭重度用户差评：「基本不可用」 <a class="header-anchor" href="#gpt-6-2-astra-与-sol-上线遭重度用户差评-「基本不可用」" aria-label="Permalink to &quot;GPT-6.2 Astra 与 Sol 上线遭重度用户差评：「基本不可用」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-11-18">2026-11-18</time></p><p>VentureBeat 报道称，OpenAI 发布 GPT-6.2 Astra 与 Sol 后，部分 AI 重度用户给出负面评价，直言「基本不可用」。这与官方宣称的专业输出和编码提升形成反差，说明新模型在真实工作流中的表现仍有争议。对读者：迁移前先用自有任务集实测，勿仅凭基准分数做切换决策。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="latent-space-astra-是第二前沿模型且便宜-20-–600-但评价分化" tabindex="-1">Latent Space：Astra 是第二前沿模型且便宜 20%–600%，但评价分化 <a class="header-anchor" href="#latent-space-astra-是第二前沿模型且便宜-20-–600-但评价分化" aria-label="Permalink to &quot;Latent Space：Astra 是第二前沿模型且便宜 20%–600%，但评价分化&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Latent Space</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7c8cafa663ba.png" alt="配图"></p><p>Latent Space 总结称 GPT-6.2 Astra 是排名第二的前沿模型，成本降低 20% 至 600%，但早期测试者对其实际使用体验意见不一；GPT-6.2 Sol 更可能成为日常主力。对读者：可把 Sol 作为默认工作模型、Astra 留给高难任务，按任务分层控制成本。</p><p class="news-entry-source"><a href="https://latent.space/p/ainews-gpt-6-2-astra-the-2-frontier-model-is-better-and-20-600-cheaper-but-has-mixed-reviews-6-2-sol/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="头条-·-nvidia-停止向中国销售-ai-芯片-黄仁勋离任后政策转向" tabindex="-1">头条 · Nvidia 停止向中国销售 AI 芯片，黄仁勋离任后政策转向 <a class="header-anchor" href="#头条-·-nvidia-停止向中国销售-ai-芯片-黄仁勋离任后政策转向" aria-label="Permalink to &quot;头条 · Nvidia 停止向中国销售 AI 芯片，黄仁勋离任后政策转向&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/164ac0ca1582.jpg" alt="配图"></p><p>Nvidia 临时 CEO Colette Kress 在财报电话会上表示，公司已不再向中国出货获许可的 Hopper 数据中心产品，尽管白宫去年 12 月已批准。此举标志着黄仁勋离任后公司对华策略的重大转变，但未解释具体原因。对读者：依赖 Nvidia 中国供应链的企业需尽快评估替代算力方案与合规风险。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/17/nvidia-is-abandoning-china-after-jensen-huangs-ouster/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nvidia-初创投资组合膨胀至-65b-黄仁勋离任令后续交易存疑" tabindex="-1">Nvidia 初创投资组合膨胀至 $65B，黄仁勋离任令后续交易存疑 <a class="header-anchor" href="#nvidia-初创投资组合膨胀至-65b-黄仁勋离任令后续交易存疑" aria-label="Permalink to &quot;Nvidia 初创投资组合膨胀至 $65B，黄仁勋离任令后续交易存疑&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e5a4bc4a4fab.jpg" alt="配图"></p><p>Nvidia 的私募投资价值在过去九个月近乎翻三倍，达到 $65B，主要受黄仁勋激进交易和既有被投企业估值上升推动。但随着黄仁勋离任，未来投资节奏面临不确定性。对读者：与 Nvidia 有资本绑定的 AI 初创需重新评估战略投资方的持续支持能力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/17/nvidias-startup-stakes-ballooned-to-65b-but-huangs-exit-puts-future-deals-in-doubt/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nvidia-董事会无意让黄仁勋回归-尽管特朗普与马斯克施压" tabindex="-1">Nvidia 董事会无意让黄仁勋回归，尽管特朗普与马斯克施压 <a class="header-anchor" href="#nvidia-董事会无意让黄仁勋回归-尽管特朗普与马斯克施压" aria-label="Permalink to &quot;Nvidia 董事会无意让黄仁勋回归，尽管特朗普与马斯克施压&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b14a9f053027.jpg" alt="配图"></p><p>Wired 报道，尽管美国总统特朗普、Elon Musk 和硅谷高管施压，Nvidia 董事会表示「不打算」恢复被罢免的 CEO 黄仁勋的职位。这为围绕 Nvidia 领导层的政治与舆论博弈再添变数。对读者：关注治理动荡对 Nvidia 产品路线与合作伙伴信心的后续影响。</p><p class="news-entry-source"><a href="https://www.wired.com/story/nvidias-board-has-no-plans-to-reinstate-jensen-huang/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="nvidia-证实不再向中国出货任何-ai-芯片" tabindex="-1">Nvidia 证实不再向中国出货任何 AI 芯片 <a class="header-anchor" href="#nvidia-证实不再向中国出货任何-ai-芯片" aria-label="Permalink to &quot;Nvidia 证实不再向中国出货任何 AI 芯片&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/34e7a2394b1e.jpg" alt="配图"></p><p>The Verge 报道，Nvidia 已停止向中国发送先进 AI 芯片，尽管去年 12 月获得白宫批准。临时 CEO Colette Kress 称业绩指引中不含任何获许可的 Hopper 数据中心产品，且不再向中国出货。对读者：关注后续是否波及 H200 等型号的许可安排，提前准备多源算力采购。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1036445/nvidia-h200-ai-chips-china-stop-selling" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="微软称-copilot-是「工作新操作系统」-office-应用已嵌入其中" tabindex="-1">微软称 Copilot 是「工作新操作系统」，Office 应用已嵌入其中 <a class="header-anchor" href="#微软称-copilot-是「工作新操作系统」-office-应用已嵌入其中" aria-label="Permalink to &quot;微软称 Copilot 是「工作新操作系统」，Office 应用已嵌入其中&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/58ac14a38fe8.png" alt="配图"></p><p>在 Microsoft Ignite 上，微软宣布 Word、Excel、PowerPoint 现已运行在 Copilot 内部，并将推出常驻 Agent。Copilot 被定位为「工作的新操作系统」，办公套件从独立应用转为 Copilot 内的能力。对读者：企业 IT 需重新评估 Office 许可与 Copilot 的捆绑方式及数据治理边界。</p><p class="news-entry-source"><a href="https://arstechnica.com/gadgets/2026/11/microsoft-calls-copilot-the-new-os-for-work-at-ignite-keynote/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="openai-发布-gpt-6-2-astra-与-sol-专业输出、编码与成本全面升级" tabindex="-1">OpenAI 发布 GPT-6.2 Astra 与 Sol：专业输出、编码与成本全面升级 <a class="header-anchor" href="#openai-发布-gpt-6-2-astra-与-sol-专业输出、编码与成本全面升级" aria-label="Permalink to &quot;OpenAI 发布 GPT-6.2 Astra 与 Sol：专业输出、编码与成本全面升级&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-18">2026-11-18</time></p><p>OpenAI 推出 GPT-6.2 Astra 与 GPT-6.2 Sol，前者面向最难的专业项目，后者定位日常高效工作，覆盖 ChatGPT Work、Codex 与 API。官方称新模型在专业输出、编码、计算机使用和效率上均有提升，且成本更低。对读者：若在用旧版 GPT-6，可优先在 Codex 与 API 场景做 A/B 对比，评估降价后的性价比。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-gpt-6-2-astra-sol" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gpt-6-2-astra-api-降价-20-至-8-40-智能指数排名第二" tabindex="-1">GPT-6.2 Astra API 降价 20% 至 $8/$40，智能指数排名第二 <a class="header-anchor" href="#gpt-6-2-astra-api-降价-20-至-8-40-智能指数排名第二" aria-label="Permalink to &quot;GPT-6.2 Astra API 降价 20% 至 $8/$40，智能指数排名第二&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-18">2026-11-18</time></p><p>OpenAI 于 11 月 17 日发布 GPT-6.2 Astra 与 Sol，Astra 的 API 价格下降 20% 至每百万 token 输入 $8、输出 $40，并在 Artificial Analysis 智能指数上排名第二。对读者：预算敏感团队可重新核算 Astra 与竞品的单位任务成本，缓存价格降幅更大值得关注。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/17/openai-gpt-6-2-astra-sol-release/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="simon-willison-astra-价格为前代-80-缓存价低至-0-40-百万" tabindex="-1">Simon Willison：Astra 价格为前代 80%，缓存价低至 $0.40/百万 <a class="header-anchor" href="#simon-willison-astra-价格为前代-80-缓存价低至-0-40-百万" aria-label="Permalink to &quot;Simon Willison：Astra 价格为前代 80%，缓存价低至 $0.40/百万&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/61f72309af9a.webp" alt="配图"></p><p>Simon Willison 指出 GPT-6.2 Astra 定价为前代 GPT-6 Astra 的 80%，即 $8/$40 每百万 token，与 Claude Fable 5.2 的降价策略一致；缓存价格从 $1/百万降至 $0.40/百万。他已发布 LLM 0.38 支持新模型。对读者：高频重复提示词场景应优先启用缓存，成本可降六成。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/17/gpt62-astra-and-sol/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gemini-tasks-在六国免费开放-深化-workspace-集成" tabindex="-1">Gemini Tasks 在六国免费开放，深化 Workspace 集成 <a class="header-anchor" href="#gemini-tasks-在六国免费开放-深化-workspace-集成" aria-label="Permalink to &quot;Gemini Tasks 在六国免费开放，深化 Workspace 集成&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/93ca97cab490.png" alt="配图"></p><p>Google 宣布 Gemini 中的 Tasks 功能在六个国家免费提供，并在美国推出新功能，同时加深与 Google Workspace 的集成，让 Gemini 代用户完成任务。对读者：已用 Workspace 的团队可试点 Tasks 自动化日常待办，评估其对协作流程的实际替代率。</p><p class="news-entry-source"><a href="https://blog.google/innovation-and-ai/products/gemini-app/tasks-in-gemini-free-new-features/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="anthropic-为-claude-code-加入-code-mode-用-javascript-链式调用工具" tabindex="-1">Anthropic 为 Claude Code 加入 Code Mode：用 JavaScript 链式调用工具 <a class="header-anchor" href="#anthropic-为-claude-code-加入-code-mode-用-javascript-链式调用工具" aria-label="Permalink to &quot;Anthropic 为 Claude Code 加入 Code Mode：用 JavaScript 链式调用工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-18">2026-11-18</time></p><p>Anthropic 在 Claude Code v2.1.323 中引入实验性 Code Mode，Claude 可编写 JavaScript 在一步内串联 Bash、Read 与 Edit 调用，并在长命令运行期间保持对话。对读者：复杂重构任务可尝试该模式减少往返轮次，但实验特性需在隔离环境验证稳定性。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/17/anthropic-claude-code-code-mode-javascript-tool-calls/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="github-构建开放-agent-host-protocol-让-agent-会话跨设备延续" tabindex="-1">GitHub 构建开放 Agent Host Protocol，让 Agent 会话跨设备延续 <a class="header-anchor" href="#github-构建开放-agent-host-protocol-让-agent-会话跨设备延续" aria-label="Permalink to &quot;GitHub 构建开放 Agent Host Protocol，让 Agent 会话跨设备延续&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-11-18">2026-11-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/bf62ed36a0ae.webp" alt="配图"></p><p>GitHub 介绍其开放 Agent Host Protocol，目标是让 Agent 会话在编辑器、应用、手机与云端之间保持可访问与延续。该协议面向多端 Agent 协作场景设计。对读者：构建跨端 Agent 产品的团队可关注该协议能否成为会话状态同步的通用层，降低自研成本。</p><p class="news-entry-source"><a href="https://github.blog/engineering/engineering-principles/building-the-agent-host-protocol-for-sessions-that-continue-across-devices/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="state-of-html-2026-结果发布-声明式特性受青睐-表单控件仍难用" tabindex="-1">State of HTML 2026 结果发布：声明式特性受青睐，表单控件仍难用 <a class="header-anchor" href="#state-of-html-2026-结果发布-声明式特性受青睐-表单控件仍难用" aria-label="Permalink to &quot;State of HTML 2026 结果发布：声明式特性受青睐，表单控件仍难用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Frontend Focus</span><time datetime="2026-11-18">2026-11-18</time></p><p>State of HTML 2026 调查结果出炉，覆盖开发者使用、喜爱与挣扎的特性及 AI 使用情况。声明式、基于元素的特性表现突出，Popover API 使用率达 40%；表单控件与日期输入仍是最难样式化的元素，可定制 select 受浏览器支持拖累。对读者：新项目可放心采用 Popover API，表单样式仍建议预留降级方案。</p><p class="news-entry-source"><a href="https://frontendfoc.us/issues/767" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
